// Insert a new node with given data at a specified position in the list
void insert_at_position(T data, int position) {
    if (position == 1 || head == nullptr) {
        insert_at_beginning(data); 
        return;
    }
    if (position < 1 || position > get_length() + 1) {
        // Append if position is invalid
        append(data); 
        return;
    }

    Node<T>* current = head;
    // Navigate to one position before desired position
    for (int i = 1; i < position - 1 && current->next != nullptr; i++) {
        current = current->next; 
    }

    Node<T>* new_node = new Node<T>({data});
    // Link new node with next node in list
    new_node->next = current->next;
    if (current->next != nullptr) {
        // Update next node's prev pointer
        current->next->prev = new_node;
    }
    // Insert new node after current node
    current->next = new_node; 
   // Link new node back to current node    
   new_node->prev = current;

    if (new_node->next == nullptr) {
        // Update tail if new node is at the end
        tail = new_node; 
    }
}
